WITH checks AS (
 SELECT 'All public tables have row security' test, NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p') AND NOT c.relrowsecurity) passed
 UNION ALL SELECT 'Browser roles cannot read credentials', NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relkind='r' AND (has_any_column_privilege('anon',c.oid,'SELECT') OR has_any_column_privilege('authenticated',c.oid,'SELECT')))
 UNION ALL SELECT 'No browser TRUNCATE privileges',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND (has_table_privilege('anon',c.oid,'TRUNCATE') OR has_table_privilege('authenticated',c.oid,'TRUNCATE')))
 UNION ALL SELECT 'Catalog writes denied',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('repo_sports_official_career_base','repo_sports_official_snapshot_meta','repo_tcg_pack_cards') AND (has_table_privilege('anon',c.oid,'INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',c.oid,'INSERT,UPDATE,DELETE')))
 UNION ALL SELECT 'Internal game functions not exposed',NOT EXISTS(SELECT 1 FROM unnest(ARRAY['public.adventure_add_inventory(uuid,text,integer)','public.adventure_ensure_daily_jobs(uuid)','public.adventure_grant_reward(uuid,text,text,integer,integer,text,integer)','public.adventure_remove_inventory(uuid,text,integer)','public.adventure_touch_internal(uuid)','public.collect_resource(uuid,text)','public.create_character(uuid,text)','public.dragonbound_ensure_personality_v2(uuid,boolean)','public.get_character(uuid)','public.repo_diver_postgame_metric(uuid,text)','public.repo_wc26_card_already_owned(uuid,text)']) f WHERE has_function_privilege('anon',f,'EXECUTE') OR has_function_privilege('authenticated',f,'EXECUTE'))
 UNION ALL SELECT 'Private room functions not exposed',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='reparty_private' AND (has_function_privilege('anon',p.oid,'EXECUTE') OR has_function_privilege('authenticated',p.oid,'EXECUTE')))
 UNION ALL SELECT 'Storage buckets are private',NOT EXISTS(SELECT 1 FROM storage.buckets WHERE public)
 UNION ALL SELECT 'Password accounts use bcrypt hashes',NOT EXISTS(SELECT 1 FROM auth.users WHERE coalesce(encrypted_password,'')<>'' AND left(encrypted_password,4) NOT IN ('$2a$','$2b$','$2y$'))
 UNION ALL SELECT 'Signed-out admin checks return false',public.is_repo_site_admin() IS FALSE AND public.adventure_is_admin() IS FALSE AND public.repo_fable_is_admin(NULL) IS FALSE
 UNION ALL SELECT 'Anonymous account rename forbidden',NOT has_function_privilege('anon','public.admin_rename_account(uuid,text)','EXECUTE')
 UNION ALL SELECT 'Browser roles cannot bypass row security',NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN ('anon','authenticated') AND (rolsuper OR rolbypassrls OR rolcreaterole))
 UNION ALL SELECT 'All privileged functions pin search paths',NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','reparty_private') AND p.prosecdef AND NOT EXISTS(SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%'))
) SELECT test,CASE WHEN passed THEN 'PASS' ELSE 'FAIL' END result FROM checks ORDER BY test;